-- Amalfi Coast launch, step 5 — editorial pass — 2026-09-26
-- Every hook re-researched against the business's own material where available plus credible
-- current sources (see docs/metro-launch-audit/amalfi/editorial-notes.md). All 39 bodies rewritten for
-- varied openers. Changes: 'Spiaggia Grande' (generic scenery) repurposed as 'Chez Black'; Il Pirata /
-- Da Adolfo / La Tagliata / Furore claims corrected to what sources verify; 2 items HELD (is_active=false,
-- reversible): 'Santa Maria de Olearia' (now a B&B, no verifiable public visit) and 'Donna Rosa'
-- (signature dish unverifiable); 1 item added ('Chiesa di San Gennaro' sunset square). Hub lists rebuilt in
-- a deliberate visiting order. Tags/difficulty/recurring/coordinates per intake rules.
BEGIN;
DO $ed$
DECLARE rec jsonb; v_id uuid; v_cat uuid; n int := 0;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements($json$[{"oldpid":"ChIJn39rOm-XOxMRUfFtSNEoScg","body":"Cut into the chocolate-and-tangerine Torta Zagara, the house cake, on the lemon-tree terrace at 'La Zagara'"},{"oldpid":"ChIJoSIkncCWOxMRb3hQoKcIt7A","body":"Hunt for the Black Madonna icon above the altar of 'Chiesa di Santa Maria Assunta', which legend says cried \"Posa, posa\" (put me down) to a storm-tossed pirate ship"},{"oldpid":"ChIJm5orj3eXOxMRdbp-qtR0VNw","body":"Descend a glass walkway over a frescoed Roman dining room, buried by Vesuvius in 79 AD, beneath Positano's church at 'MAR Positano'"},{"oldpid":"ChIJzxm5RG-XOxMRiyc4qbt4UHM","body":"Choose a leather and watch a third-generation cobbler build sandals to your feet in minutes at 'Artigianato Rallo'"},{"oldpid":"ChIJoUijgBeXOxMRayKHsUIVhIs","body":"Board the free boat from Positano's pier to 'Ristorante Da Adolfo', where lunch means mozzarella grilled on lemon leaves","d":1},{"oldpid":"ChIJeZDhvGeXOxMRtumC1QyEOpQ","body":"Slip past 16th-century Torre Trasita on the cliff-carved Via Positanesi d'America to swim at 'Fornillo Beach'"},{"oldpid":"ChIJ4coKSfOWOxMRR84g-JLxTp0","body":"Hike the 8 km 'Sentiero degli Dei' from Bomerano to Nocelle, then descend the stairs toward Positano"},{"oldpid":"ChIJ3QOeIGmXOxMRHI25GddJioI","body":"Sail out at sunset with 'Lucibello' to Li Galli, Rudolf Nureyev's former island, for a swim, snorkel and prosecco","core":["boat","island","swimming","adventure","scenic"],"sec":["boat-tour","unique","sunset"],"alc":true},{"oldpid":"ChIJuxunJW-XOxMRd-7kxOP4ih0","body":"Grab a first-come seat before sunset on the raft-like terrace of 'Franco's Bar', where Franco's Fizz is the signature"},{"oldpid":"ChIJJbN_PpiXOxMR54BkeDpk_Ps","body":"Trace three generations of famous guests along the logbook photo wall and order the sea urchin at 'Chez Black', on Spiaggia Grande since 1949","pid":"ChIJTVr63miXOxMRKMOIeBJLsIQ","lat":40.6280498,"lng":14.4869969,"addr":"Via del Brigantino, 19, 84017 Positano SA, Italy","web":"http://www.chezblack.it/","mq":"Chez Black, Via del Brigantino, 19, 84017 Positano SA, Italy","cat":"Food & drink","core":["seafood","italian","restaurant","historic","waterfront"],"sec":["beach","local-favorite","dinner"],"alc":false,"rec":true,"d":1,"r":100},{"oldpid":"ChIJtehEnnKXOxMRQW_dziDhCSY","body":"Climb the rock-cut steps to the hole in the mountain above 'Montepertuso', pierced, says legend, when the Virgin Mary blew through the rock after the Devil failed"},{"oldpid":"ChIJjdDMD22XOxMRb7rKwBYWLd4","body":"Hop the free shuttle up to 'Il Ritrovo' in Montepertuso for its house zuppa saracena, a Positano-style fish soup"},{"oldpid":"ChIJnyb6U22XOxMRPqQQIlxuono","body":"Wander the organic vegetable terraces of 'La Tagliata' before a charcoal-grilled dinner of free-range local meat","core":["farm-to-table","italian","restaurant","views","local-favorite"],"sec":["dinner","unique","hidden-gem"]},{"oldpid":"ChIJP0CXFRGXOxMRsXndziDhCSY","body":"Tackle roughly 1,500 stone steps up to 'Nocelle', the car-free hamlet 400 meters above Positano with a view across to Capri"},{"oldpid":"ChIJV95oyhSXOxMRxN7yxlMzDaA","body":"Reserve a day at 'Arienzo Beach Club' and ride its shuttle boat from Spiaggia Grande to a cove otherwise reached by 300 steps"},{"oldpid":"ChIJD9xcIcGWOxMR91xRR_aqtfI","body":"Eat linguine with mixed seafood at a table between the cliff and the emerald cove of Marina di Praia at 'Trattoria Da Armandino'"},{"oldpid":"ChIJX_vjxcaWOxMRzId7DK-_hzY","body":"Unwind in the lounge bar built into a natural cave at 'Il Pirata', on the water below Praiano"},{"oldpid":"ChIJHZNLy6KWOxMRky7R0i10ybI","body":"Peer over the 30-meter Furore bridge into the sea-filled gorge of 'Fiordo di Furore', home to an annual cliff-jumping championship"},{"oldpid":"ChIJiba0jiOUOxMR2CXzsykurq4","body":"Book a tasting in the rock-carved cellar of 'Cantine Marisa Cuomo' to try Fiorduva, a white from rare Fenile, Ginestra and Ripoli grapes"},{"oldpid":"ChIJO1U7OiCUOxMRzbZo5uEs74s","body":"Drift past stalagmites and a sunken ceramic nativity scene by boat inside 'Grotta dello Smeraldo', reached by cliffside elevator"},{"oldpid":"ChIJ9fRPa66VOxMRT7NHgkwo0NQ","body":"Break open a sfogliatella Santa Rosa, or bag candied lemon peel, at 'Pasticceria Andrea Pansa' on the cathedral piazza since 1830"},{"oldpid":"ChIJ8zyce66VOxMR40XBRZb-75c","body":"Count the slender Moorish arches around the palm garden of 'Chiostro del Paradiso', built in 1266 as Amalfi's noble burial ground"},{"oldpid":"ChIJrSB4qrqVOxMR3io9z2JxH9Y","body":"Watch centuries-old water-driven hammers pulp rags into handmade paper inside the 13th-century mill of 'Museo della Carta'"},{"oldpid":"ChIJY6QNZ7qVOxMRDpLNLrtkNJ8","body":"Walk the Acetos family's terraced lemon groves and finish with homemade limoncello at 'Amalfi Lemon Experience'"},{"oldpid":"ChIJob5w0K2VOxMRvCvlIHjVUDw","body":"Duck under the cross vaults of the 'Arsenale della Repubblica', the only medieval shipyard still in its original form"},{"oldpid":"ChIJb8673Z-VOxMR3IhhgAAESjk","body":"Stand where Wagner imagined Klingsor's magic garden for Parsifal in 1880, on the flower terraces of 'Villa Rufolo'"},{"oldpid":"ChIJKx2evqCVOxMRx5wEJfjT_hw","body":"Reach the Terrace of Infinity, a cliff-top belvedere edged with marble busts, at 'Villa Cimbrone'"},{"oldpid":"ChIJqdTnAOSVOxMRY-xwBm8ZlIk","body":"Read the 80 panels of the 1179 bronze doors, then the lion-footed, mosaic-columned pulpit of 1272, inside the 'Duomo di Ravello'"},{"oldpid":"ChIJ-1VsFp2VOxMRkWWbxT2PR8w","body":"Pick lemons from the terraced garden and learn Amalfi Coast home cooking at 'Mamma Agata' cooking school"},{"oldpid":"ChIJn0v50J-VOxMR0AN89IkM-gk","body":"Share the crespolini, pasta crepes baked with prosciutto and cheese, at 'Trattoria Cumpà Cosimo'"},{"oldpid":"ChIJmTYS6pGVOxMR0Ni0mUa1dNc","body":"Trek along a fern-lined stream from Pontone to Amalfi past waterfalls and medieval ironworks ruins in the 'Valle delle Ferriere'"},{"oldpid":"ChIJY28zxnKVOxMRVnO5EuZCWoE","body":"Order Salvatore De Riso's signature Delizia al Limone at 'Pasticceria Sal De Riso', open daily until 1 a.m."},{"oldpid":"ChIJp6jL62uVOxMR_ByLIkG1qFo","body":"Stroll between Minori and Maiori on the 'Sentiero dei Limoni', past terraced lemon groves and the thousand-year-old church at Torre"},{"oldpid":"ChIJ0brwPIbqOxMRROfsAnsAT78","body":"Buy amber colatura di alici, the drip from barrels of salted anchovies that descends from Roman garum, at 'Delfino Battista'"},{"oldpid":"ChIJ35HnE4bqOxMRs8OgoMfwhAY","body":"Twirl spaghetti dressed with Cetara's colatura di alici inside a former medieval convent at 'Al Convento'"},{"oldpid":"ChIJE5uiI-vBOxMROIkcmrn9_mM","body":"Follow the spiral ramp through Paolo Soleri's 1953 factory, its facade studded with ceramic vases, at 'Ceramica Artistica Solimene'"},{"oldpid":"ChIJQ8ew6VXBOxMRXWIk3uCWEYM","body":"Look up at the 36-meter majolica dome of 'Chiesa di San Giovanni Battista', tiled in Vietri's green, yellow and blue"}]$json$::jsonb) LOOP
    SELECT i.id INTO v_id FROM public.items i JOIN public.neighborhoods nb ON nb.id=i.neighborhood_id
      WHERE nb.metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821' AND i.google_place_id = rec->>'oldpid';
    IF v_id IS NULL THEN RAISE EXCEPTION 'item not found for place %', rec->>'oldpid'; END IF;
    UPDATE public.items SET body = rec->>'body',
      google_place_id = COALESCE(rec->>'pid', google_place_id),
      maps_lat = COALESCE((rec->>'lat')::float8, maps_lat), maps_lng = COALESCE((rec->>'lng')::float8, maps_lng),
      formatted_address = COALESCE(rec->>'addr', formatted_address), website_url = CASE WHEN rec ? 'pid' THEN rec->>'web' ELSE website_url END,
      maps_query = COALESCE(rec->>'mq', maps_query),
      category_id = COALESCE((SELECT id FROM public.categories WHERE name = rec->>'cat'), category_id),
      has_alcohol = COALESCE((rec->>'alc')::boolean, has_alcohol), is_recurring = COALESCE((rec->>'rec')::boolean, is_recurring),
      difficulty = COALESCE((rec->>'d')::int, difficulty), geo_radius_m = COALESCE((rec->>'r')::float8, geo_radius_m)
    WHERE id = v_id;
    IF rec ? 'core' THEN
      IF (SELECT count(*) FROM public.tags WHERE name IN (SELECT jsonb_array_elements_text((rec->'core')||(rec->'sec')))) <> 8 THEN RAISE EXCEPTION 'tags for %', rec->>'body'; END IF;
      DELETE FROM public.item_tags WHERE item_id = v_id;
      INSERT INTO public.item_tags (item_id, tag_id, source, confidence) SELECT v_id, t.id, 'auto', 1.0 FROM public.tags t WHERE t.name IN (SELECT jsonb_array_elements_text(rec->'core'));
      INSERT INTO public.item_tags (item_id, tag_id, source, confidence) SELECT v_id, t.id, 'auto', 0.9 FROM public.tags t WHERE t.name IN (SELECT jsonb_array_elements_text(rec->'sec'));
    END IF;
    n := n + 1;
  END LOOP;
  IF n <> 37 THEN RAISE EXCEPTION 'expected 37 updates, did %', n; END IF;

  -- new item
  rec := $json${"k":"sangennaro","nb":"36f99ec8-4deb-4599-9e92-27845665b1ec","cat":"Travel","body":"Time your arrival for sunset on the majolica-tiled square outside 'Chiesa di San Gennaro' in Praiano, with Positano, Li Galli and Capri in view","mq":"Parish Church of Saint Januarius, Piazza S. Gennaro, 1, 84010 Praiano SA, Italy","lat":40.6122386,"lng":14.5225766,"pid":"ChIJ0fkRn9CWOxMRdwj6EDXG3UM","addr":"Piazza S. Gennaro, 1, 84010 Praiano SA, Italy","web":"https://tally.so/r/zxAA21","alc":false,"rec":false,"d":1,"r":120,"core":["church","views","sunset","scenic","architecture"],"sec":["photo-op","landmark","local-culture"]}$json$::jsonb;
  SELECT id INTO v_cat FROM public.categories WHERE name = rec->>'cat';
  IF (SELECT count(*) FROM public.tags WHERE name IN (SELECT jsonb_array_elements_text((rec->'core')||(rec->'sec')))) <> 8 THEN RAISE EXCEPTION 'tags new item'; END IF;
  INSERT INTO public.items (body, category_id, neighborhood_id, checkin_type, maps_query, maps_lat, maps_lng, geo_radius_m, is_universal, is_active, is_approved, is_recurring, difficulty, photo_required, has_alcohol, google_place_id, formatted_address, website_url)
  VALUES (rec->>'body', v_cat, (rec->>'nb')::uuid, 'tap', rec->>'mq', (rec->>'lat')::float8, (rec->>'lng')::float8, (rec->>'r')::float8, false, true, true, (rec->>'rec')::boolean, (rec->>'d')::int, false, (rec->>'alc')::boolean, rec->>'pid', rec->>'addr', rec->>'web')
  RETURNING id INTO v_id;
  INSERT INTO public.item_tags (item_id, tag_id, source, confidence) SELECT v_id, t.id, 'auto', 1.0 FROM public.tags t WHERE t.name IN (SELECT jsonb_array_elements_text(rec->'core'));
  INSERT INTO public.item_tags (item_id, tag_id, source, confidence) SELECT v_id, t.id, 'auto', 0.9 FROM public.tags t WHERE t.name IN (SELECT jsonb_array_elements_text(rec->'sec'));
END $ed$;

