  ('fb5ed539-39ad-43c9-aae6-f6597a5ee76e', (SELECT id FROM public.items WHERE google_place_id='ChIJm5orj3eXOxMRdbp-qtR0VNw' AND neighborhood_id IN (SELECT id FROM public.neighborhoods WHERE metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821')), 3),
  ('fb5ed539-39ad-43c9-aae6-f6597a5ee76e', (SELECT id FROM public.items WHERE google_place_id='ChIJzxm5RG-XOxMRiyc4qbt4UHM' AND neighborhood_id IN (SELECT id FROM public.neighborhoods WHERE metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821')), 4),
  ('fb5ed539-39ad-43c9-aae6-f6597a5ee76e', (SELECT id FROM public.items WHERE google_place_id='ChIJoUijgBeXOxMRayKHsUIVhIs' AND neighborhood_id IN (SELECT id FROM public.neighborhoods WHERE metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821')), 5),
  ('fb5ed539-39ad-43c9-aae6-f6597a5ee76e', (SELECT id FROM public.items WHERE google_place_id='ChIJeZDhvGeXOxMRtumC1QyEOpQ' AND neighborhood_id IN (SELECT id FROM public.neighborhoods WHERE metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821')), 6),
