  ('fb5ed539-39ad-43c9-aae6-f6597a5ee76e', (SELECT id FROM public.items WHERE google_place_id='ChIJTVr63miXOxMRKMOIeBJLsIQ' AND neighborhood_id IN (SELECT id FROM public.neighborhoods WHERE metro_id='b3e00b75-59f0-4b8f-ad3a-f6a203365821')), 10),
